/// Writes the CityCore Swift for validated game data, keyed by file name.
/// Output depends only on the data: cases follow load order and goods
/// inside a value are sorted by id, so two runs are byte-identical.
public enum SwiftEmitter {
    public static let banner = """
    // GENERATED by gamedata-gen from Packages/CityCore/GameData.
    // Do not edit: change the packs, then run `make gamedata`.

    import Foundation

    """

    public static func emit(_ data: GameData) -> [String: String] {
        [
            "Good+Generated.swift": goods(data),
            "BuildingKind+Generated.swift": buildings(data),
            "ProductionCatalog+Generated.swift": recipes(data),
            "Culture+Generated.swift": cultures(data),
            "Tech+Generated.swift": techs(data),
            "Age+Generated.swift": ages(data)
        ].mapValues { banner + $0 }
    }

    // MARK: - Files

    private static func goods(_ data: GameData) -> String {
        let all = data.goods
        return enumDecl("Good", "String, CaseIterable, Codable, Sendable", all.map(\.id))
            + extensionDecl("Good", [
                property("basePrice", "Int64", all.map { ($0.id, "\($0.basePrice)") })
            ])
            + catalog("GoodsCatalog", spec: "GoodSpec", for: "good", of: "Good", all.map { good in
                (good.id, "GoodSpec(good: .\(caseName(good.id)), displayName: \(literal(good.name)), stackUnit: \(literal(good.unit)))")
            })
    }

    private static func buildings(_ data: GameData) -> String {
        let all = data.buildings
        return enumDecl("BuildingKind", "String, CaseIterable, Sendable", all.map(\.id))
            + codable(aliases: all.flatMap { building in building.legacyIds.map { ($0, building.id) } })
            + extensionDecl("BuildingKind", [
                property("displayName", "String", all.map { ($0.id, literal($0.name ?? titleCased($0.id))) }),
                property("storage", "Int?", all.map { ($0.id, $0.storage.map(String.init) ?? "nil") }),
                property("category", "String?", all.map { ($0.id, $0.category.map(literal) ?? "nil") }),
                property("culture", "Culture?", all.map { ($0.id, optionalCase($0.culture)) }),
                property("obsoletedBy", "Tech?", all.map { ($0.id, optionalCase($0.obsoletedBy)) })
            ])
            + catalog("BuildingCatalog", spec: "BuildingSpec", for: "kind", of: "BuildingKind", all.map { ($0.id, spec($0)) })
    }

    private static func recipes(_ data: GameData) -> String {
        let cases = data.buildings.map { building in
            (building.id, building.recipe.map(recipe) ?? "nil")
        }
        return "\npublic enum ProductionCatalog {\n"
            + function("public static func recipe(for kind: BuildingKind) -> ProductionRecipe?", over: "kind", cases)
            + "}\n"
    }

    private static func cultures(_ data: GameData) -> String {
        let all = data.cultures
        let tierNames = all.flatMap { culture in
            houseTiers.map { tier in
                ("(.\(caseName(culture.id)), .\(tier))", literal(culture.tiers[tier] ?? ""))
            }
        }
        return enumDecl("Culture", "String, CaseIterable, Codable, Hashable, Sendable", all.map(\.id))
            + extensionDecl("Culture", [
                property("displayName", "String", all.map { ($0.id, literal($0.name)) }),
                property("blurb", "String", all.map { ($0.id, literal($0.blurb)) }),
                property("luxuryChain", "LuxuryChain", all.map { ($0.id, luxury($0.luxury)) }),
                property("signature", "BuildingKind", all.map { ($0.id, ".\(caseName($0.signature))") }),
                property("residentNames", "[String]", all.map { ($0.id, "[\($0.residentNames.map(literal).joined(separator: ", "))]") }),
                all.isEmpty ? "" : "\n" + function(
                    "func tierName(_ tier: HouseTier) -> String", over: "(self, tier)", tierNames, quoted: false
                )
            ])
    }

    private static func techs(_ data: GameData) -> String {
        let all = data.techs
        return enumDecl("Tech", "String, CaseIterable, Codable, Sendable", all.map(\.id))
            + extensionDecl("Tech", [
                property("displayName", "String", all.map { ($0.id, literal($0.name ?? titleCased($0.id))) }),
                property("cost", "Int", all.map { ($0.id, "\($0.cost)") }),
                property("prerequisites", "[Tech]", all.map { ($0.id, caseList($0.prerequisites)) }),
                property("unlocks", "[BuildingKind]", all.map { ($0.id, caseList(data.unlocks(of: $0.id))) }),
                property("age", "Age", all.map { ($0.id, ".\(caseName($0.age))") }),
                property("era", "Age?", all.map { ($0.id, optionalCase($0.era)) }),
                property("eraGate", "(tier: HouseTier, residents: Int)?", all.map { tech in
                    (tech.id, tech.eraGate.map { "(.\($0.tier), \($0.residents))" } ?? "nil")
                })
            ])
    }

    private static func ages(_ data: GameData) -> String {
        let all = data.ages
        return enumDecl("Age", "String, CaseIterable, Codable, Hashable, Sendable", all.map(\.id))
            + extensionDecl("Age", [
                property("displayName", "String", all.map { ($0.id, literal($0.name ?? titleCased($0.id))) }),
                property("startYear", "Int", all.map { ($0.id, "\($0.startYear)") }),
                property("blurb", "String", all.map { ($0.id, literal($0.blurb)) }),
                property("signature", "BuildingKind", all.map { ($0.id, ".\(caseName($0.signature))") }),
                property("rivalResidents", "Int", all.map { ($0.id, "\($0.rivalResidents)") })
            ])
    }

    // MARK: - Values

    private static func spec(_ building: Building) -> String {
        var shore = "nil", terrain = "nil"
        switch building.placement {
        case let .shore(land, water)?: shore = "ShorePlacement(minLandTiles: \(land), minWaterTiles: \(water))"
        case let .terrain(type, tiles)?: terrain = "TerrainRequirement(terrain: .\(type), minTiles: \(tiles))"
        case nil: break
        }
        return "BuildingSpec(kind: .\(caseName(building.id)), "
            + "footprint: Footprint(width: \(building.footprint.width), height: \(building.footprint.height)), "
            + "cost: \(building.cost), upkeep: \(building.upkeep), buildDurationTicks: \(building.buildTicks), "
            + "shorePlacement: \(shore), materialCost: \(amounts(building.materials)), requiredTerrain: \(terrain))"
    }

    private static func recipe(_ recipe: Recipe) -> String {
        "ProductionRecipe(inputs: \(amounts(recipe.inputs)), outputs: \(amounts(recipe.outputs)), cycleTicks: \(recipe.cycleTicks))"
    }

    private static func luxury(_ chain: LuxuryChain) -> String {
        "LuxuryChain(raw: .\(caseName(chain.raw)), good: .\(caseName(chain.good)), "
            + "garden: .\(caseName(chain.garden)), producer: .\(caseName(chain.producer)))"
    }

    /// `[.planks: 1, .wood: 4]`, sorted by good id.
    private static func amounts(_ amounts: GoodAmounts) -> String {
        guard !amounts.isEmpty else { return "[:]" }
        return "[" + amounts.sorted { $0.good < $1.good }.map { ".\(caseName($0.good)): \($0.amount)" }.joined(separator: ", ") + "]"
    }

    private static func optionalCase(_ id: String?) -> String {
        id.map { ".\(caseName($0))" } ?? "nil"
    }

    private static func caseList(_ ids: [String]) -> String {
        "[" + ids.map { ".\(caseName($0))" }.joined(separator: ", ") + "]"
    }

    // MARK: - Declarations

    private static func enumDecl(_ name: String, _ conformances: String, _ ids: [String]) -> String {
        let cases = ids.map { id in
            let name = caseName(id)
            return name == id ? "    case \(name)\n" : "    case \(name) = \(literal(id))\n"
        }
        return "\npublic enum \(name): \(conformances) {\n\(cases.joined())}\n"
    }

    private static func codable(aliases: [(legacy: String, current: String)]) -> String {
        let canonical = aliases.isEmpty ? "raw" : "switch raw {\n"
            + aliases.map { "        case \(literal($0.legacy)): \(literal($0.current))\n" }.joined()
            + "        default: raw\n        }"
        return """

        extension BuildingKind: Codable {
            public init(from decoder: Decoder) throws {
                let raw = try decoder.singleValueContainer().decode(String.self)
                let canonical = \(canonical)
                guard let kind = BuildingKind(rawValue: canonical) else {
                    throw DecodingError.dataCorrupted(
                        .init(codingPath: decoder.codingPath, debugDescription: "Unknown BuildingKind raw value: \\(raw)")
                    )
                }
                self = kind
            }

            public func encode(to encoder: Encoder) throws {
                var container = encoder.singleValueContainer()
                try container.encode(rawValue)
            }
        }

        """
    }

    /// A catalog with `spec(for:)` as one exhaustive `switch`, and `all`
    /// in case order.
    private static func catalog(
        _ name: String,
        spec: String,
        for parameter: String,
        of type: String,
        _ values: [(String, String)]
    ) -> String {
        "\npublic enum \(name) {\n"
            + "    public static var all: [\(spec)] {\n        \(type).allCases.map(spec(for:))\n    }\n\n"
            + function("public static func spec(for \(parameter): \(type)) -> \(spec)", over: parameter, values)
            + "}\n"
    }

    private static func extensionDecl(_ type: String, _ members: [String]) -> String {
        "\npublic extension \(type) {\n" + members.filter { !$0.isEmpty }.joined(separator: "\n") + "}\n"
    }

    /// A computed property as one exhaustive `switch`, one case per line.
    private static func property(_ name: String, _ type: String, _ values: [(String, String)]) -> String {
        values.isEmpty ? "" : function("var \(name): \(type)", over: "self", values)
    }

    /// `signature` whose body switches over `subject`. Case patterns are
    /// ids turned into `.caseName` unless `quoted` is false.
    private static func function(_ signature: String, over subject: String, _ values: [(String, String)], quoted: Bool = true) -> String {
        let cases = values.map { pattern, value in
            "        case \(quoted ? ".\(caseName(pattern))" : pattern): \(value)\n"
        }
        return "    \(signature) {\n        switch \(subject) {\n\(cases.joined())        }\n    }\n"
    }

    // MARK: - Names

    private static let keywords: Set<String> = [
        "as", "case", "class", "default", "do", "else", "enum", "extension", "false", "for", "func", "if", "import",
        "in", "init", "inout", "internal", "is", "let", "nil", "operator", "private", "protocol", "public", "repeat", "return", "self",
        "static", "struct", "super", "switch", "throw", "true", "try", "var", "where", "while"
    ]

    /// `lumberjack-hut` → `lumberjackHut`; keywords are back-quoted.
    static func caseName(_ id: String) -> String {
        let words = id.split(separator: "-")
        let name = (words.first.map(String.init) ?? "") + words.dropFirst().map { $0.prefix(1).uppercased() + $0.dropFirst() }.joined()
        return keywords.contains(name) ? "`\(name)`" : name
    }

    /// `grain-farm` → `Grain Farm`.
    static func titleCased(_ id: String) -> String {
        id.split(separator: "-").map { $0.prefix(1).uppercased() + $0.dropFirst() }.joined(separator: " ")
    }

    static func literal(_ text: String) -> String {
        String(reflecting: text)
    }
}
